#!/usr/bin/env python3
import os
import sys
import json
import shlex
import subprocess
import re
from urllib.parse import urlsplit, quote, unquote

VERSION = "handlr 0.6.4"
DEFAULT_CONFIG = "enable_selector = false\nselector = \"rofi -dmenu -i -p 'Open With: '\"\n"

SUBCOMMANDS = {
    "list": "List default apps and the associated handlers",
    "open": "Open a path/URL with its default handler",
    "set": "Set the default handler for mime/extension",
    "unset": "Unset the default handler for mime/extension",
    "launch": "Launch the handler for specified extension/mime with optional arguments",
    "get": "Get handler for this mime/extension",
    "add": "Add a handler for given mime/extension Note that the first handler is the default",
}

# ---------------------------------------------------------------------------
# Paths and startup files


def home_dir():
    return os.environ.get("HOME") or os.path.expanduser("~")


def config_home():
    val = os.environ.get("XDG_CONFIG_HOME")
    if val:
        return val
    return os.path.join(home_dir(), ".config")


def data_home():
    val = os.environ.get("XDG_DATA_HOME")
    if val:
        return val
    return os.path.join(home_dir(), ".local", "share")


def xdg_data_dirs():
    if "XDG_DATA_DIRS" in os.environ:
        val = os.environ.get("XDG_DATA_DIRS", "")
        return [p for p in val.split(":") if p]
    return ["/usr/local/share", "/usr/share"]


def app_dirs():
    return [os.path.join(data_home(), "applications")] + [os.path.join(d, "applications") for d in xdg_data_dirs()]


def mimeapps_path():
    return os.path.join(config_home(), "mimeapps.list")


def handlr_config_path():
    return os.path.join(config_home(), "handlr", "handlr.toml")


def ensure_startup_files():
    # The original eagerly creates both files before doing argument handling.
    cdir = config_home()
    os.makedirs(cdir, exist_ok=True)
    mpath = mimeapps_path()
    if not os.path.exists(mpath):
        open(mpath, "a", encoding="utf-8").close()
    hpath = handlr_config_path()
    os.makedirs(os.path.dirname(hpath), exist_ok=True)
    if not os.path.exists(hpath):
        with open(hpath, "w", encoding="utf-8") as f:
            f.write(DEFAULT_CONFIG)


# ---------------------------------------------------------------------------
# Help and error output


def prog_name():
    return os.path.basename(sys.argv[0]) or "executable"


def root_help(name=None):
    if name is None:
        name = prog_name()
    return (f"{VERSION}\n\n"
            f"USAGE:\n"
            f"    {name} <SUBCOMMAND>\n\n"
            f"FLAGS:\n"
            f"    -h, --help       Prints help information\n"
            f"    -V, --version    Prints version information\n\n"
            f"SUBCOMMANDS:\n"
            f"    list      List default apps and the associated handlers\n"
            f"    open      Open a path/URL with its default handler\n"
            f"    set       Set the default handler for mime/extension\n"
            f"    unset     Unset the default handler for mime/extension\n"
            f"    launch    Launch the handler for specified extension/mime with optional arguments\n"
            f"    get       Get handler for this mime/extension\n"
            f"    add       Add a handler for given mime/extension Note that the first handler is the default\n")


def sub_help(cmd, name=None):
    if name is None:
        name = prog_name()
    first = f"{name}-{cmd} \n"
    if cmd == "open":
        return (first + "Open a path/URL with its default handler\n\n"
                f"USAGE:\n    {name} open <paths>...\n\n"
                "ARGS:\n    <paths>...    \n\n"
                "FLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n")
    if cmd == "set":
        return (first + "Set the default handler for mime/extension\n\n"
                f"USAGE:\n    {name} set <mime> <handler>\n\n"
                "ARGS:\n    <mime>       \n    <handler>    \n\n"
                "FLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n")
    if cmd == "add":
        return (first + "Add a handler for given mime/extension Note that the first handler is the default\n\n"
                f"USAGE:\n    {name} add <mime> <handler>\n\n"
                "ARGS:\n    <mime>       \n    <handler>    \n\n"
                "FLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n")
    if cmd == "unset":
        return (first + "Unset the default handler for mime/extension\n\n"
                f"USAGE:\n    {name} unset <mime>\n\n"
                "ARGS:\n    <mime>    \n\n"
                "FLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n")
    if cmd == "get":
        return (first + "Get handler for this mime/extension\n\n"
                f"USAGE:\n    {name} get [FLAGS] <mime>\n\n"
                "ARGS:\n    <mime>    \n\n"
                "FLAGS:\n        --json       \n    -h, --help       Prints help information\n    -V, --version    Prints version information\n")
    if cmd == "list":
        return (first + "List default apps and the associated handlers\n\n"
                f"USAGE:\n    {name} list [FLAGS]\n\n"
                "FLAGS:\n    -a, --all        \n    -h, --help       Prints help information\n    -V, --version    Prints version information\n")
    if cmd == "launch":
        return (first + "Launch the handler for specified extension/mime with optional arguments\n\n"
                f"USAGE:\n    {name} launch <mime> [args]...\n\n"
                "ARGS:\n    <mime>       \n    <args>...    \n\n"
                "FLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n")
    return ""


def usage_for(cmd, name=None, alt_json_equals=False):
    if name is None:
        name = prog_name()
    if cmd == "root":
        return f"{name} <SUBCOMMAND>"
    if cmd == "open":
        return f"{name} open <paths>..."
    if cmd == "set":
        return f"{name} set <mime> <handler>"
    if cmd == "add":
        return f"{name} add <mime> <handler>"
    if cmd == "unset":
        return f"{name} unset <mime>"
    if cmd == "get":
        if alt_json_equals:
            return f"{name} get <mime> --json"
        return f"{name} get [FLAGS] <mime>"
    if cmd == "list":
        return f"{name} list [FLAGS]"
    if cmd == "launch":
        return f"{name} launch <mime> [args]..."
    return name


def eprint(s):
    sys.stderr.write(s)


def cli_unknown(arg, cmd="root"):
    use = usage_for(cmd)
    eprint(f"error: Found argument '{arg}' which wasn't expected, or isn't valid in this context\n\n"
           f"If you tried to supply `{arg}` as a PATTERN use `-- {arg}`\n\n"
           f"USAGE:\n    {use}\n\n"
           f"For more information try --help\n")
    return 2


def cli_missing(cmd, names, alt_json_equals=False):
    eprint("error: The following required arguments were not provided:\n")
    for n in names:
        eprint(f"    {n}\n")
    eprint("\n")
    eprint(f"USAGE:\n    {usage_for(cmd, alt_json_equals=alt_json_equals)}\n\n")
    eprint("For more information try --help\n")
    return 2


def cli_duplicate(flag, cmd):
    canonical = "--all" if flag in ("-a", "--all") else flag
    eprint(f"error: The argument '{canonical}' was provided more than once, but cannot be used multiple times\n\n"
           f"USAGE:\n    {usage_for(cmd)}\n\n"
           f"For more information try --help\n")
    return 2


def cli_invalid_value(name, msg):
    eprint(f"error: Invalid value for '{name}': {msg}\n\n"
           f"For more information try --help\n")
    return 2


def runtime_notfound():
    eprint('Error: Io(Os { code: 2, kind: NotFound, message: "No such file or directory" })\n')
    return 1


def runtime_io_from_exc(exc):
    if isinstance(exc, FileNotFoundError):
        return runtime_notfound()
    code = getattr(exc, "errno", None) or 1
    msg = getattr(exc, "strerror", None) or str(exc)
    kind = "PermissionDenied" if code == 13 else "Other"
    eprint(f'Error: Io(Os {{ code: {code}, kind: {kind}, message: "{msg}" }})\n')
    return 1


def panic_user_selector():
    eprint(f"\nthread 'main' ({os.getpid()}) panicked at src/apps/user.rs:67:26:\n"
           "called `Option::unwrap()` on a `None` value\n"
           "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    return 101


def panic_desktop_entry():
    eprint(f"\nthread 'main' ({os.getpid()}) panicked at src/common/desktop_entry.rs:65:49:\n"
           "called `Option::unwrap()` on a `None` value\n"
           "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    return 101


# ---------------------------------------------------------------------------
# MIME parsing and URL/file classification

TOKEN_CHARS = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$&^_.+-*")


def parse_mime_arg(value):
    # The observed binary attempts file-based detection for dot-prefixed inputs;
    # in this environment that path returns this diagnostic for all such values.
    if value.startswith('.'):
        return None, f"could not figure out the mime type of '{value}'"

    semi = value.find(';')
    main = value if semi == -1 else value[:semi]
    if '/' not in main:
        return None, "mime parse error: a slash (/) was missing between the type and subtype"

    slash = main.find('/')
    # Validate type, including empty type (slash at position 0).
    if slash == 0:
        return None, "mime parse error: an invalid token was encountered, 2F at position 0"
    for i, ch in enumerate(main[:slash]):
        if ch not in TOKEN_CHARS:
            return None, f"mime parse error: an invalid token was encountered, {ord(ch):02X} at position {i}"

    subtype = main[slash+1:]
    if subtype == "":
        return None, f"bad mime: {main}"
    for j, ch in enumerate(subtype):
        pos = slash + 1 + j
        if ch not in TOKEN_CHARS:
            return None, f"mime parse error: an invalid token was encountered, {ord(ch):02X} at position {pos}"

    return main[:slash].lower() + "/" + subtype.lower(), None


def mime_type_part(mime):
    return mime.split('/', 1)[0]


def classify_path_or_url(arg):
    m = re.match(r'^([A-Za-z][A-Za-z0-9+.-]*):(.*)$', arg, re.S)
    if m:
        scheme_orig = m.group(1)
        scheme = scheme_orig.lower()
        rest = m.group(2)
        if scheme == "file":
            try:
                sp = urlsplit(scheme + ":" + rest)
            except Exception:
                sp = None
            if sp is not None:
                netloc = sp.netloc
                path = unquote(sp.path or "")
                if netloc and netloc.lower() != "localhost":
                    return None, None, f"Bad path: {path}"
                target = path
            else:
                target = unquote(rest)
            mime = "inode/directory" if os.path.isdir(target) else "application/x-zerosize"
            return target, mime, None
        target = normalize_url(scheme, rest)
        return target, f"x-scheme-handler/{scheme}", None
    else:
        mime = "inode/directory" if os.path.isdir(arg) else "application/x-zerosize"
        return arg, mime, None


def normalize_url(scheme, rest):
    # url::Url normalizes special schemes more than opaque/custom schemes.
    raw = scheme + ":" + rest
    if scheme in ("http", "https", "ftp"):
        sp = urlsplit(raw)
        netloc = sp.netloc
        path = sp.path
        query = sp.query
        fragment = sp.fragment
        if not netloc and path and not path.startswith('/'):
            # e.g. http:foo => http://foo/
            netloc = path
            path = "/"
        if netloc:
            netloc = lower_host_in_netloc(netloc)
        if path == "":
            path = "/"
        path_q = quote(path, safe="/%:@!$&'()*+,;=-._~")
        query_q = quote(query, safe="/?%:@!$&'()*+,;=-._~")
        out = f"{scheme}://{netloc}{path_q}"
        if query:
            out += "?" + query_q
        if fragment:
            out += "#" + quote(fragment, safe="/?%:@!$&'()*+,;=-._~")
        return out
    if scheme == "mailto":
        sp = urlsplit(raw)
        path = sp.path
        query = sp.query
        frag = sp.fragment
        out = scheme + ":" + quote(path, safe="/%:@!$&'()*+,;=-._~")
        if query:
            out += "?" + quote(query, safe="/?%:@!$&'()*+,;=-._~")
        if frag:
            out += "#" + quote(frag, safe="/?%:@!$&'()*+,;=-._~")
        return out
    # For custom schemes, observed behavior lowercases only the scheme and
    # otherwise preserves the rest.
    return scheme + ":" + rest


def lower_host_in_netloc(netloc):
    # Preserve userinfo/port, lowercase only host-ish portion.
    userinfo = ""
    hostport = netloc
    if "@" in hostport:
        userinfo, hostport = hostport.rsplit("@", 1)
        userinfo += "@"
    if hostport.startswith("["):
        # IPv6 literal: lowercase until closing bracket, preserve port.
        end = hostport.find("]")
        if end != -1:
            return userinfo + hostport[:end+1].lower() + hostport[end+1:]
    if ":" in hostport:
        host, port = hostport.rsplit(":", 1)
        if port.isdigit():
            return userinfo + host.lower() + ":" + port
    return userinfo + hostport.lower()


# ---------------------------------------------------------------------------
# Desktop entries and applications

class DesktopEntry:
    __slots__ = ("handler", "path", "name", "exec_line", "mimetypes")

    def __init__(self, handler, path, name, exec_line, mimetypes):
        self.handler = handler
        self.path = path
        self.name = name
        self.exec_line = exec_line
        self.mimetypes = mimetypes


def read_desktop_file(path, handler):
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            lines = f.read().splitlines()
    except OSError:
        return None
    in_group = False
    values = {}
    for raw in lines:
        line = raw.strip()
        if not line:
            continue
        if line.startswith('#'):
            continue
        if line.startswith('[') and line.endswith(']'):
            in_group = (line == "[Desktop Entry]")
            continue
        if not in_group:
            continue
        if '=' not in raw:
            continue
        key, val = raw.split('=', 1)
        key = key.strip()
        val = strip_inline_comment(val.rstrip('\r'))
        # Use unlocalized Name only.
        if key in ("Name", "Exec", "MimeType"):
            values[key] = val
    name = values.get("Name", "")
    exec_line = values.get("Exec", "")
    if name == "" or exec_line == "":
        return None
    mimes = []
    if "MimeType" in values:
        for m in values.get("MimeType", "").split(';'):
            if m:
                mimes.append(m)
    return DesktopEntry(handler, path, name, exec_line, mimes)


def strip_inline_comment(val):
    # The parser used by the observed program drops an inline '#...' in simple
    # desktop values. Do the same when # begins after whitespace.
    out = []
    in_s = False
    in_d = False
    esc = False
    prev_space = True
    for ch in val:
        if esc:
            out.append(ch)
            esc = False
            prev_space = ch.isspace()
            continue
        if ch == '\\':
            out.append(ch)
            esc = True
            prev_space = False
            continue
        if ch == "'" and not in_d:
            in_s = not in_s
        elif ch == '"' and not in_s:
            in_d = not in_d
        if ch == '#' and not in_s and not in_d and prev_space:
            break
        out.append(ch)
        prev_space = ch.isspace()
    return ''.join(out).strip()


def discover_top_level_apps():
    entries = {}
    order = []
    for d in app_dirs():
        try:
            names = os.listdir(d)
        except OSError:
            continue
        # os.listdir on ext filesystems yields the same creation-ish order the
        # benchmarked binary exposed via read_dir; do not sort here.
        for name in names:
            if not name.endswith(".desktop"):
                continue
            p = os.path.join(d, name)
            if not os.path.isfile(p):
                continue
            if name in entries:
                continue
            ent = read_desktop_file(p, name)
            if ent is None:
                continue
            entries[name] = ent
            order.append(name)
    return entries, order


def resolve_handler(handler, top_entries=None):
    if top_entries is None:
        top_entries, _ = discover_top_level_apps()
    # Absolute path is parsed directly if it exists.
    if os.path.isabs(handler):
        if not os.path.exists(handler):
            return None, "notfound", None
        ent = read_desktop_file(handler, handler)
        if ent is None:
            return None, "malformed", handler
        return ent, None, handler
    # Relative path containing slashes is relative to applications dirs.
    if '/' in handler:
        for d in app_dirs():
            p = os.path.join(d, handler)
            if os.path.exists(p):
                ent = read_desktop_file(p, handler)
                if ent is None:
                    return None, "malformed", p
                return ent, None, p
        return None, "notfound", None
    ent = top_entries.get(handler)
    if ent is not None:
        return ent, None, ent.path
    return None, "notfound", None


def validate_handler_for_cli(handler):
    top, _ = discover_top_level_apps()
    ent, err, path = resolve_handler(handler, top)
    if err == "notfound":
        return None, f"no handlers found for '{handler}'"
    if err == "malformed":
        return None, f"malformed desktop entry at {path}"
    return ent, None


def system_apps_map():
    entries, order = discover_top_level_apps()
    m = {}
    for hid in order:
        ent = entries[hid]
        for mt in ent.mimetypes:
            m.setdefault(mt, [])
            if hid not in m[mt]:
                m[mt].append(hid)
    return m


# ---------------------------------------------------------------------------
# mimeapps.list

class MimeApps:
    def __init__(self, added=None, defaults=None):
        self.added = added if added is not None else []  # list of (key, rawvalue)
        self.defaults = defaults if defaults is not None else {}  # key -> [handlers]


def parse_mimeapps():
    path = mimeapps_path()
    added = []
    defaults = {}
    section = None
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            lines = f.read().splitlines()
    except OSError:
        return MimeApps()
    for raw in lines:
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        if line.startswith('[') and line.endswith(']'):
            section = line[1:-1]
            continue
        if '=' not in raw:
            continue
        key, val = raw.split('=', 1)
        key = key.strip()
        val = val.strip()
        if section == "Added Associations":
            added.append((key, val))
        elif section == "Default Applications":
            handlers = [h for h in val.split(';') if h]
            defaults[key] = handlers  # last duplicate wins
    return MimeApps(added, defaults)


def filter_valid_handlers(handlers, top_entries=None, dedupe=False):
    if top_entries is None:
        top_entries, _ = discover_top_level_apps()
    out = []
    ents = []
    seen = set()
    for h in handlers:
        ent, err, _path = resolve_handler(h, top_entries)
        if ent is None:
            continue
        if dedupe and h in seen:
            continue
        seen.add(h)
        out.append(h)
        ents.append(ent)
    return out, ents


def clean_defaults(defaults):
    top, _ = discover_top_level_apps()
    cleaned = {}
    for k, handlers in defaults.items():
        valid, _ = filter_valid_handlers(handlers, top, dedupe=False)
        if valid:
            cleaned[k] = valid
    return cleaned


def write_mimeapps(ma):
    os.makedirs(os.path.dirname(mimeapps_path()), exist_ok=True)
    with open(mimeapps_path(), "w", encoding="utf-8") as f:
        f.write("[Added Associations]\n")
        for k, v in ma.added:
            f.write(f"{k}={v}\n")
        f.write("\n[Default Applications]\n")
        for k in sorted(ma.defaults.keys()):
            vals = ma.defaults[k]
            if not vals:
                continue
            f.write(f"{k}=" + ";".join(vals) + ";\n")


# ---------------------------------------------------------------------------
# Lookup, selector, tables, JSON


def read_selector_config():
    enabled = False
    selector = "rofi -dmenu -i -p 'Open With: '"
    try:
        with open(handlr_config_path(), "r", encoding="utf-8", errors="replace") as f:
            for raw in f:
                line = raw.strip()
                if not line or line.startswith('#') or '=' not in line:
                    continue
                key, val = line.split('=', 1)
                key = key.strip()
                val = val.strip()
                if key == "enable_selector":
                    enabled = val.lower().startswith('true')
                elif key == "selector":
                    if len(val) >= 2 and val[0] == '"' and val[-1] == '"':
                        try:
                            # shlex-style unquote is sufficient for observed TOML strings.
                            selector = shlex.split(val)[0]
                        except Exception:
                            selector = val[1:-1]
                    else:
                        selector = val
    except OSError:
        pass
    return enabled, selector


def choose_with_selector(handler_ids, entries):
    # handler_ids and entries are already valid and deduplicated as needed.
    if not handler_ids:
        return None, None, 1
    enabled, selector_cmd = read_selector_config()
    if enabled and len(handler_ids) > 1:
        names = [e.name for e in entries]
        stdin = "\n".join(names)
        try:
            argv = shlex.split(selector_cmd)
            cp = subprocess.run(argv, input=stdin, text=True, stdout=subprocess.PIPE)
            choice = cp.stdout.strip()
        except OSError as exc:
            return None, None, runtime_io_from_exc(exc)
        if choice:
            for hid, ent in zip(handler_ids, entries):
                if ent.name == choice:
                    return hid, ent, 0
            return None, None, panic_user_selector()
    return handler_ids[0], entries[0], 0


def lookup_handler(mime):
    ma = parse_mimeapps()
    top, _ = discover_top_level_apps()

    # User exact.
    for key in (mime, f"{mime_type_part(mime)}/*"):
        if key in ma.defaults:
            ids, ents = filter_valid_handlers(ma.defaults[key], top, dedupe=True)
            if ids:
                return choose_with_selector(ids, ents)
        if key == mime and mime.endswith('/*'):
            # For an exact wildcard query, do not also synthesize type/* twice.
            break

    # System exact only; observed lookup does not use wildcard MimeType entries.
    smap = system_apps_map()
    if mime in smap:
        ids, ents = filter_valid_handlers(smap[mime], top, dedupe=True)
        if ids:
            return choose_with_selector(ids, ents)
    return None, None, runtime_notfound()


def table(rows):
    if not rows:
        return "┌──┐\n│  │\n└──┘\n"
    w1 = max(len(r[0]) for r in rows)
    w2 = max(len(r[1]) for r in rows)
    out = []
    out.append("┌" + "─"*(w1+2) + "┬" + "─"*(w2+2) + "┐")
    for a, b in rows:
        out.append("│ " + a.ljust(w1) + " │ " + b.ljust(w2) + " │")
    out.append("└" + "─"*(w1+2) + "┴" + "─"*(w2+2) + "┘")
    return "\n".join(out) + "\n"


def default_rows():
    ma = parse_mimeapps()
    top, _ = discover_top_level_apps()
    rows = []
    for k in sorted(ma.defaults.keys()):
        ids, _ = filter_valid_handlers(ma.defaults[k], top, dedupe=True)
        if ids:
            rows.append((k, ", ".join(ids)))
    return rows


def system_rows():
    smap = system_apps_map()
    rows = []
    for k in sorted(smap.keys()):
        vals = []
        seen = set()
        for h in smap[k]:
            if h not in seen:
                seen.add(h)
                vals.append(h)
        if vals:
            rows.append((k, ", ".join(vals)))
    return rows


def parse_exec_args(exec_line):
    try:
        return shlex.split(exec_line, comments=True, posix=True)
    except Exception:
        return None


FIELD_CODES = ("%f", "%F", "%u", "%U")
UPPER_FIELD_CODES = ("%F", "%U")


def json_cmd(exec_line):
    args = parse_exec_args(exec_line)
    if args is None:
        return None
    out = []
    for tok in args:
        nt = tok
        for code in FIELD_CODES:
            nt = nt.replace(code, "")
        if nt != "":
            out.append(nt)
    return " ".join(out)


def expand_exec_args(exec_line, launch_args, append_if_no_field=True):
    args = parse_exec_args(exec_line)
    if args is None:
        return None
    has_field = any(code in tok for tok in args for code in FIELD_CODES)
    expanded = []
    joined = " ".join(launch_args)
    for tok in args:
        if tok in FIELD_CODES:
            expanded.extend(launch_args)
        else:
            nt = tok
            for code in FIELD_CODES:
                nt = nt.replace(code, joined)
            if nt != "":
                expanded.append(nt)
    if not has_field and append_if_no_field:
        expanded.extend(launch_args)
    return expanded


def spawn_exec(exec_line, args):
    argv = expand_exec_args(exec_line, args, append_if_no_field=True)
    if argv is None:
        return panic_desktop_entry()
    if not argv:
        return runtime_notfound()
    try:
        subprocess.Popen(argv, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except OSError as exc:
        return runtime_io_from_exc(exc)
    return 0


def open_spawn_entry(ent, targets):
    args = parse_exec_args(ent.exec_line)
    if args is None:
        return panic_desktop_entry()
    has_upper = any(code in tok for tok in args for code in UPPER_FIELD_CODES)
    if has_upper:
        return spawn_exec(ent.exec_line, targets)
    for t in targets:
        rc = spawn_exec(ent.exec_line, [t])
        if rc != 0:
            return rc
    return 0


# ---------------------------------------------------------------------------
# Command implementations


def cmd_get(mime, as_json):
    hid, ent, rc = lookup_handler(mime)
    if rc != 0:
        return rc
    if as_json:
        cmd = json_cmd(ent.exec_line)
        if cmd is None:
            return panic_desktop_entry()
        obj = {"handler": hid, "name": ent.name, "cmd": cmd}
        sys.stdout.write(json.dumps(obj, ensure_ascii=False, separators=(",", ":")) + "\n")
    else:
        sys.stdout.write(hid + "\n")
    return 0


def cmd_list(all_flag):
    if all_flag:
        sys.stdout.write("Default Apps\n")
        sys.stdout.write(table(default_rows()))
        sys.stdout.write("System Apps\n")
        sys.stdout.write(table(system_rows()))
    else:
        sys.stdout.write(table(default_rows()))
    return 0


def cmd_set_or_add(mime, handler, add=False):
    ent, herr = validate_handler_for_cli(handler)
    if herr:
        return cli_invalid_value("<handler>", herr)
    ma = parse_mimeapps()
    ma.defaults = clean_defaults(ma.defaults)
    if add and mime in ma.defaults:
        ma.defaults[mime].append(handler)
    else:
        ma.defaults[mime] = [handler]
    write_mimeapps(ma)
    return 0


def cmd_unset(mime):
    ma = parse_mimeapps()
    ma.defaults = clean_defaults(ma.defaults)
    if mime in ma.defaults:
        del ma.defaults[mime]
    write_mimeapps(ma)
    return 0


def cmd_launch(mime, args):
    hid, ent, rc = lookup_handler(mime)
    if rc != 0:
        return rc
    return spawn_exec(ent.exec_line, args)


def cmd_open(paths):
    # First validate/classify and resolve all handlers. No children are launched
    # if any target fails resolution.
    groups = []  # list of [handler, ent, targets]
    by_handler = {}
    for p in paths:
        target, mime, err = classify_path_or_url(p)
        if err:
            return cli_invalid_value("<paths>...", err)
        hid, ent, rc = lookup_handler(mime)
        if rc != 0:
            return rc
        if hid not in by_handler:
            group = [hid, ent, []]
            by_handler[hid] = group
            groups.append(group)
        by_handler[hid][2].append(target)
    for _hid, ent, targets in groups:
        rc = open_spawn_entry(ent, targets)
        if rc != 0:
            return rc
    return 0


# ---------------------------------------------------------------------------
# Minimal Clap-like argument parsing


def split_flags_positionals(args, allowed_flags, cmd, allow_after_double_dash=True):
    flags = []
    pos = []
    stop = False
    alt_json_equals = False
    for a in args:
        if not stop and a == "--":
            stop = True
            continue
        if not stop and a in ("-h", "--help"):
            return "help", [], [], False
        if not stop and a in ("-V", "--version"):
            return "version", [], [], False
        if not stop and a.startswith("--json=") and "--json" in allowed_flags:
            # Clap treats this as the flag being present with no positional, for
            # the cases we observed.
            flags.append("--json")
            alt_json_equals = True
            continue
        if not stop and a.startswith('-'):
            if a in allowed_flags:
                flags.append(a)
            else:
                return "unknown", a, [], False
        else:
            pos.append(a)
    return flags, pos, None, alt_json_equals


def parse_no_option_positionals(args, cmd, min_count, max_count=None):
    # Used for set/add/unset; hyphen values require --, and help/version win.
    pos = []
    stop = False
    for a in args:
        if not stop and a == "--":
            stop = True
            continue
        if not stop and a in ("-h", "--help"):
            return "help", [], None
        if not stop and a in ("-V", "--version"):
            return "version", [], None
        if not stop and a.startswith('-'):
            return "unknown", a, None
        pos.append(a)
    return "ok", pos, None


def handle_get(args):
    parsed, pos, _dummy, alt = split_flags_positionals(args, {"--json"}, "get")
    if parsed == "help":
        sys.stdout.write(sub_help("get")); return 0
    if parsed == "version":
        sys.stdout.write(f"{prog_name()}-get \n"); return 0
    if parsed == "unknown":
        return cli_unknown(pos, "get")
    flags = parsed
    if flags.count("--json") > 1:
        return cli_duplicate("--json", "get")
    as_json = "--json" in flags
    if len(pos) < 1:
        return cli_missing("get", ["<mime>"], alt_json_equals=alt)
    if len(pos) > 1:
        return cli_unknown(pos[1], "get")
    mime, err = parse_mime_arg(pos[0])
    if err:
        return cli_invalid_value("<mime>", err)
    return cmd_get(mime, as_json)


def handle_list(args):
    parsed, pos, _dummy, _alt = split_flags_positionals(args, {"-a", "--all"}, "list")
    if parsed == "help":
        sys.stdout.write(sub_help("list")); return 0
    if parsed == "version":
        sys.stdout.write(f"{prog_name()}-list \n"); return 0
    if parsed == "unknown":
        return cli_unknown(pos, "list")
    flags = parsed
    all_count = sum(1 for f in flags if f in ("-a", "--all"))
    if all_count > 1:
        return cli_duplicate("--all", "list")
    if pos:
        return cli_unknown(pos[0], "list")
    return cmd_list(all_count == 1)


def handle_set_add(cmd, args):
    state, pos, _ = parse_no_option_positionals(args, cmd, 2, 2)
    if state == "help":
        sys.stdout.write(sub_help(cmd)); return 0
    if state == "version":
        sys.stdout.write(f"{prog_name()}-{cmd} \n"); return 0
    if state == "unknown":
        return cli_unknown(pos, cmd)
    if len(pos) < 2:
        missing = []
        if len(pos) < 1:
            missing.append("<mime>")
        if len(pos) < 2:
            missing.append("<handler>")
        return cli_missing(cmd, missing)
    if len(pos) > 2:
        return cli_unknown(pos[2], cmd)
    mime, err = parse_mime_arg(pos[0])
    if err:
        return cli_invalid_value("<mime>", err)
    return cmd_set_or_add(mime, pos[1], add=(cmd == "add"))


def handle_unset(args):
    state, pos, _ = parse_no_option_positionals(args, "unset", 1, 1)
    if state == "help":
        sys.stdout.write(sub_help("unset")); return 0
    if state == "version":
        sys.stdout.write(f"{prog_name()}-unset \n"); return 0
    if state == "unknown":
        return cli_unknown(pos, "unset")
    if len(pos) < 1:
        return cli_missing("unset", ["<mime>"])
    if len(pos) > 1:
        return cli_unknown(pos[1], "unset")
    mime, err = parse_mime_arg(pos[0])
    if err:
        return cli_invalid_value("<mime>", err)
    return cmd_unset(mime)


def handle_launch(args):
    pos = []
    stop = False
    for a in args:
        if not stop and a == "--":
            stop = True
            continue
        if not stop and a in ("-h", "--help"):
            sys.stdout.write(sub_help("launch")); return 0
        if not stop and a in ("-V", "--version"):
            sys.stdout.write(f"{prog_name()}-launch \n"); return 0
        if not stop and a.startswith('-'):
            return cli_unknown(a, "launch")
        pos.append(a)
    if len(pos) < 1:
        return cli_missing("launch", ["<mime>"])
    mime, err = parse_mime_arg(pos[0])
    if err:
        return cli_invalid_value("<mime>", err)
    return cmd_launch(mime, pos[1:])


def handle_open(args):
    pos = []
    stop = False
    for a in args:
        if not stop and a == "--":
            stop = True
            continue
        if not stop and a in ("-h", "--help"):
            sys.stdout.write(sub_help("open")); return 0
        if not stop and a in ("-V", "--version"):
            sys.stdout.write(f"{prog_name()}-open \n"); return 0
        if not stop and a.startswith('-'):
            return cli_unknown(a, "open")
        pos.append(a)
    if len(pos) < 1:
        return cli_missing("open", ["<paths>..."])
    return cmd_open(pos)


def main(argv):
    ensure_startup_files()
    name = prog_name()
    if not argv:
        eprint(root_help(name))
        return 2
    first = argv[0]
    if first in ("-h", "--help"):
        sys.stdout.write(root_help(name)); return 0
    if first in ("-V", "--version"):
        sys.stdout.write(VERSION + "\n"); return 0
    if first == "list":
        return handle_list(argv[1:])
    if first == "open":
        return handle_open(argv[1:])
    if first == "set":
        return handle_set_add("set", argv[1:])
    if first == "add":
        return handle_set_add("add", argv[1:])
    if first == "unset":
        return handle_unset(argv[1:])
    if first == "launch":
        return handle_launch(argv[1:])
    if first == "get":
        return handle_get(argv[1:])
    if first == "--" and len(argv) > 1:
        return cli_unknown(argv[1], "root")
    return cli_unknown(first, "root")


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv[1:]))
    except BrokenPipeError:
        sys.exit(1)
